from .repository import contact_exists, put_contact

_FIELDS = frozenset({"email", "name"})


def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)


def _normalize_row(index, row):
    if not isinstance(row, dict):
        raise ValueError(f"row {index}: must be an object")
    keys = set(row.keys())
    if keys != _FIELDS:
        missing = sorted(_FIELDS - keys, key=str)
        unknown = sorted(keys - _FIELDS, key=str)
        raise ValueError(f"row {index}: missing fields {missing}, unknown fields {unknown}")
    email, name = row["email"], row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError(f"row {index}: email and name must be strings")
    email = email.strip()
    name = name.strip()
    if any(ch.isspace() for ch in email):
        raise ValueError(f"row {index}: email must not contain whitespace")
    if email.count("@") != 1:
        raise ValueError(f"row {index}: email must contain exactly one @")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError(f"row {index}: email must have nonempty sides around @")
    if not name:
        raise ValueError(f"row {index}: name must be nonempty")
    return email.lower(), name


def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    normalized = []
    seen = set()
    for index, row in enumerate(rows):
        email, name = _normalize_row(index, row)
        if email in seen:
            raise ValueError(f"row {index}: duplicate email {email!r} in batch")
        seen.add(email)
        normalized.append((email, name))

    summary = {"inserted": 0, "updated": 0}
    if not normalized:
        return summary
    # `with connection` commits on success and rolls back on any exception,
    # so a database failure mid-batch leaves contacts unchanged.
    with connection:
        connection.execute("BEGIN")
        for email, name in normalized:
            if contact_exists(connection, email):
                summary["updated"] += 1
            else:
                summary["inserted"] += 1
            put_contact(connection, email, name)
    return summary
EOF
